import {jsPDF} from 'jspdf';
import html2canvas from 'html2canvas';
import * as pdfjsLib from 'pdfjs-dist/build/pdf';
const $=id=>document.getElementById(id), metaIds=['title','student','roll','college','course','year','guide','font','layout','university','degree','institutionDetails','students','reportDate','recommendation','certificateText','acknowledgement'];
let type='assignment',images=[],sections=[],built=null,busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setBusy(value){busy=value;document.querySelectorAll('#generate,#pdf,#docx,#print,#organise,#sample,#sample2,#save,#reset').forEach(b=>b.disabled=value);$('progress').hidden=!value;document.body.classList.toggle('working',value);document.querySelector('.editor').inert=value}
const status=(s,error=false)=>{$('status').textContent=s;$('status').className=error?'error':''};
const fileName=()=>($('title').value||'project').replace(/[^a-z0-9\u0900-\u097f]+/gi,'-').slice(0,70)||'project';
const download=(blob,name)=>{let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),60000)};
function invalidate(){built=null;$('downloads').hidden=true;$('pages').innerHTML='';$('empty').hidden=false;$('count').textContent='A4';$('previewTools').hidden=true;$('reviewChecks').hidden=true;}
function chooseType(t){type=t;document.querySelectorAll('.type').forEach(b=>b.classList.toggle('active',b.dataset.type===t));$('blackbookFields').hidden=t!=='blackbook';$('font').disabled=t==='blackbook';$('layout').disabled=t==='blackbook';$('certificate').disabled=t==='blackbook';$('certificate').parentElement.hidden=t==='blackbook';document.querySelectorAll('.type').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.type===t)));invalidate()}
document.querySelectorAll('.type').forEach(b=>b.onclick=()=>chooseType(b.dataset.type));
metaIds.forEach(id=>$(id).addEventListener('input',invalidate));$('certificate').onchange=invalidate;
$('content').oninput=()=>{updateCount();sections=[];$('sectionList').innerHTML='';invalidate()};
const known=/^(abstract|introduction|overview|objectives?|problem statement|literature review|existing system|proposed system|methodology|system analysis|system design|architecture|implementation|testing|results?(?: and discussion)?|discussion|conclusions?|future scope|references|bibliography|acknowledg(?:e)?ments?|appendix|requirements?|limitations?|प्रस्तावना|परिचय|उद्देश्य|निष्कर्ष|संदर्भ|सारांश|आभार|कृतज्ञता|मनोगत|परिचय|उद्दिष्टे|निष्कर्ष|पद्धती|कार्यपद्धती|अंमलबजावणी|भविष्यातील व्याप्ती|संदर्भ सूची)$/i;
function parseContent(text){let out=[],cur={title:type==='assignment'?'Assignment content':'Project content',paras:[]},buf=[];
 const flush=()=>{if(buf.length){cur.paras.push(buf.join('\n').trim());buf=[]}};
 const start=head=>{flush();if(cur.paras.length||out.length)out.push(cur);cur={title:head,paras:[]}};
 let lines=text.replace(/\r/g,'').split('\n');for(let ix=0;ix<lines.length;ix++){let line=lines[ix].trim();if(!line){flush();continue}
 if(/^#{2,3}\s+/.test(line)||/^\d+\.\d+(?:\.\d+)*\s+\S/.test(line)){flush();cur.paras.push(line);continue}
 let chapter=line.match(/^chapter\s+\d+\s*[:.\-]?\s*(.*)$/i);if(chapter){let title=chapter[1].trim();if(!title){let j=ix+1;while(j<lines.length&&!lines[j].trim())j++;if(j<lines.length&&lines[j].trim().length<120){title=lines[j].trim();ix=j}}start(title||line);continue}
 let match=line.match(/^#\s+(.+)$/),clean=line.replace(/^\d+[.)]?\s+/,'').replace(/:$/,'').trim();let head=match?.[1]||((known.test(clean)||/^[A-Z][A-Z \d/&()-]{3,70}$/.test(line))?clean:null);
 if(head)start(head);else buf.push(line)}flush();if(cur.paras.length||cur.title!=='Project content')out.push(cur);return out.filter(s=>s.paras.length||s.title).map((s,i)=>({...s,id:'s'+i}))}
function tokenize(s){return (s.toLowerCase().match(/[a-z0-9\u0900-\u097f]{3,}/g)||[]).filter(w=>!['the','and','for','with','this','that','image','jpg','png','webp','screenshot','figure'].includes(w))}
function autoMatch(im){let keys=tokenize(im.caption+' '+im.name);let scores=sections.map(s=>{let title=tokenize(s.title),body=tokenize(s.paras.join(' '));return keys.reduce((n,k)=>n+(title.includes(k)?5:body.includes(k)?1:0),0)});let best=Math.max(...scores);return best>0?sections[scores.indexOf(best)]?.id:sections[0]?.id}
function organise(){updateCount();sections=parseContent($('content').value);for(let im of images)if(!sections.some(s=>s.id===im.section)){im.section=autoMatch(im);im.automatic=true}renderSections();renderImages();invalidate();status(`${sections.length} sections found. Review titles, order and image placement before building.`)}
function syncContent(){$('content').value=sections.map(s=>'# '+s.title+'\n\n'+s.paras.join('\n\n')).join('\n\n');updateCount()}
function updateCount(){$('textCount').textContent=$('content').value.length.toLocaleString()+' / 300,000 characters'}
function renderSections(){$('sectionList').innerHTML=sections.map((s,i)=>`<div class="sectioncard"><div class="sectiontop"><span>${i+1}</span><input aria-label="Section ${i+1} title" value="${esc(s.title)}" data-section="${i}"><button data-up="${i}" ${i===0?'disabled':''} aria-label="Move section ${i+1} up">↑</button><button data-down="${i}" ${i===sections.length-1?'disabled':''} aria-label="Move section ${i+1} down">↓</button></div><details><summary>Edit section text · ${s.paras.join(' ').length.toLocaleString()} characters</summary><textarea aria-label="Section ${i+1} text" data-body="${i}" rows="5">${esc(s.paras.join('\n\n'))}</textarea><button class="textbtn" data-diag="${i}" type="button">+ Auto diagram from this section</button></details></div>`).join('');$('sectionList').querySelectorAll('[data-section]').forEach(el=>el.oninput=()=>{sections[+el.dataset.section].title=el.value;syncContent();renderImages();invalidate()});$('sectionList').querySelectorAll('[data-body]').forEach(el=>el.oninput=()=>{sections[+el.dataset.body].paras=el.value.split(/\n\s*\n/).filter(p=>p.trim());syncContent();invalidate()});$('sectionList').querySelectorAll('button[data-up],button[data-down]').forEach(b=>b.onclick=()=>{let i=+(b.dataset.up??b.dataset.down),j=i+(b.dataset.up!==undefined?-1:1);if(j<0||j>=sections.length)return;[sections[i],sections[j]]=[sections[j],sections[i]];syncContent();renderSections();renderImages();invalidate()})}
function renderImages(){$('imageList').innerHTML=images.map((im,i)=>`<div class="imgcard"><img src="${im.data}" alt="Uploaded image ${i+1}"><div><label>Caption<input value="${esc(im.caption)}" data-caption="${i}" maxlength="400"></label><label>Place in section<select data-placement="${i}">${sections.length?sections.map(s=>`<option value="${s.id}" ${s.id===im.section?'selected':''}>${esc(s.title)}</option>`).join(''):'<option>Organise content first</option>'}</select></label><label>Image position<select data-anchor="${i}"><option value="end" ${im.anchor==='end'?'selected':''}>After section text</option><option value="start" ${im.anchor==='start'?'selected':''}>After section heading</option></select></label><small class="micro">${im.automatic?'Suggested from caption / filename. Please check.':'Your placement.'}</small></div><button class="textbtn" data-remove="${i}">Remove image</button></div>`).join('');$('imageList').querySelectorAll('[data-caption]').forEach(el=>el.oninput=()=>{images[+el.dataset.caption].caption=el.value;invalidate()});$('imageList').querySelectorAll('[data-placement]').forEach(el=>el.onchange=()=>{Object.assign(images[+el.dataset.placement],{section:el.value,automatic:false});invalidate()});$('imageList').querySelectorAll('[data-anchor]').forEach(el=>el.onchange=()=>{images[+el.dataset.anchor].anchor=el.value;invalidate()});$('imageList').querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{images.splice(+el.dataset.remove,1);renderImages();invalidate()})}
async function imageFromFile(f){if(!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Only PNG, JPG and WebP images are supported.');if(f.size>10*1024*1024)throw Error(`${f.name} exceeds 10 MB.`);let data=await new Promise((resolve,reject)=>{let r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});let im=await new Promise((resolve,reject)=>{let i=new Image;i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Could not read '+f.name));i.src=data});let scale=Math.min(1,1600/Math.max(im.width,im.height)),w=Math.round(im.width*scale),h=Math.round(im.height*scale);let c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);return {name:f.name,caption:f.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' '),data:c.toDataURL('image/png'),w,h,anchor:'end',automatic:true}}
$('images').onchange=async e=>{try{for(let f of e.target.files){if(images.length>=12)throw Error('Maximum 12 images.');let im=await imageFromFile(f);im.section=autoMatch(im);images.push(im)}renderImages();invalidate();status('Images added. Check captions and section placements.')}catch(err){status(err.message,true)}e.target.value=''};
$('organise').onclick=organise;
function studentLines(m){return m.students?m.students.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>{let [name,...prn]=x.split('|');return name.trim()+(prn.length?' (PRN: '+prn.join('|').trim()+')':'')}):[m.student||'Student name',...(m.roll?['Roll / PRN: '+m.roll]:[])]}
function blockHTML(b){if(b.kind==='heading')return `<h2>${b.chapter?'<span class="chapterlabel">'+L('chapter')+' '+b.chapter+'</span>':''}${esc(b.text)}</h2>`;if(b.kind==='image')return `<figure><img src="${b.im.data}" style="width:${b.width}px;height:${b.height}px" alt="${esc(b.im.caption)}"><figcaption>${esc(b.text)}</figcaption></figure>`;if(b.kind==='tochead')return '<div class="tocrow tochead"><span>'+L('chapno')+'</span><span>'+L('title')+'</span><span>'+L('pageno')+'</span></div>';if(b.kind==='toc')return `<div class="tocrow ${b.chapter?'chaptertoc':''}">${b.chapter?'<span>'+b.chapter+'</span>':''}<span>${esc(b.text)}</span><span>${b.number}</span></div>`;return `<p class="${b.kind==='subhead'?'subhead':b.kind==='list'?'list':b.kind==='left'?'left':b.kind==='center'?'center':b.kind==='letterhead'?'letterhead':b.kind==='bigtitle'?'bigtitle':b.kind==='draft'?'draft':''}">${esc(b.text)}</p>`}
function pageHTML(p,n,total,m){let bb=m.type==='blackbook',foot=bb?`<div class="pagefoot">${n}</div>`:`<div class="pagefoot"><span>${esc(m.title)}</span><span>${n} / ${total}</span></div>`;let body=p.cover?(bb?`<div class="cover bookcover cs-${m.coverStyle||'classic'}" style="--acc:${m.coverAccent||'#4c3fd1'}">${logoHTML()}<div class="coverintro">${L('aprojectreport')}</div><h1>${esc(m.title)}</h1><p>${L('submitted')}<br><strong>${studentLines(m).map(esc).join('<br>')}</strong></p>${m.guide?'<p>'+L('guidance')+'<br><strong>'+esc(m.guide)+'</strong></p>':''}<p>${esc(m.degree||m.course)}${m.university?'<br>'+L('of')+'<br><strong>'+esc(m.university)+'</strong>':''}</p><div>${esc(m.year)}</div><div class="institution">${esc(m.college||'Institution name')}</div></div>`:`<div class="cover cs-${m.coverStyle||'classic'}" style="--acc:${m.coverAccent||'#4c3fd1'}">${logoHTML()}<div class="institution">${esc(m.college||'Institution name')}</div><div class="coverkind">${{assignment:L('assignment'),project:L('projectreport')}[m.type]}</div><div class="rule"></div><h1>${esc(m.title)}</h1><p>${L('submitted')}<br><strong>${esc(m.student||'Student name')}</strong>${m.roll?'<br>Roll / PRN: '+esc(m.roll):''}</p>${m.guide?'<p>'+L('guidance')+'<br><strong>'+esc(m.guide)+'</strong></p>':''}<p>${esc(m.course)}</p><div class="year">${esc(m.year)}</div></div>`):p.blocks.map(blockHTML).join('');return `<div class="page ${bb?'blackbook':m.font==='sans'?'sans':''}"><div class="pagebody">${body}</div>${foot}</div>`}
function paginate(blocks,m){let pages=[],page={blocks:[]};$('measure').innerHTML=pageHTML(page,1,1,m);let body=$('measure').querySelector('.pagebody');let fits=bs=>{body.innerHTML=bs.map(blockHTML).join('');return body.scrollHeight<=body.clientHeight};let push=()=>{if(page.blocks.length)pages.push(page);page={blocks:[]}};
 for(let ix=0;ix<blocks.length;ix++){let b=blocks[ix];if(b.kind==='heading'&&m.layout==='chapters'&&(m.type!=='blackbook'||b.chapter)&&page.blocks.length)push();if(b.kind==='heading'&&blocks[ix+1]&&page.blocks.length){let next=blocks[ix+1],test=next.kind==='text'?{...next,text:next.text.slice(0,200)}:next;if(!fits([...page.blocks,b,test]))push()}
 if(fits([...page.blocks,b])){page.blocks.push(b);continue}if(['image','heading','toc','tochead'].includes(b.kind)){push();if(!fits([b]))throw Error('A heading or caption is too long. Shorten it and rebuild.');page.blocks.push(b);continue}
 let remaining=b.text;while(remaining){if(fits([...page.blocks,{...b,text:remaining}])){page.blocks.push({...b,text:remaining});break}let low=0,high=remaining.length;while(low<high){let mid=Math.ceil((low+high)/2);if(fits([...page.blocks,{...b,text:remaining.slice(0,mid)}]))low=mid;else high=mid-1}if(low<50&&page.blocks.length){push();continue}if(low===0)throw Error('Could not paginate this content.');let cut=low;let space=remaining.lastIndexOf(' ',low);if(space>low*.75)cut=space;page.blocks.push({...b,text:remaining.slice(0,cut).trimEnd()});remaining=remaining.slice(cut).trimStart();push()}}
 push();return pages}
function contentBlocks(m){let out=[],fig=0,chapter=0;for(let s of sections){if(m.type==='blackbook'&&/^(abstract|acknowledg(?:e)?ments?|सारांश|आभार|कृतज्ञता|मनोगत)$/i.test(s.title))continue;out.push({kind:'heading',text:s.title,section:s.id,chapter:m.type==='blackbook'?++chapter:null});let ims=images.filter(im=>im.section===s.id);let ib=im=>{let scale=Math.min(1,(m.type==='blackbook'?678:636)/im.w,(m.type==='blackbook'?600:390)/im.h),width=Math.round(im.w*scale),height=Math.round(im.h*scale);return{kind:'image',im,width,height,text:`Figure ${++fig}: ${im.caption||im.name}`}};ims.filter(im=>im.anchor==='start').forEach(im=>out.push(ib(im)));s.paras.forEach(p=>{let lines=p.split('\n');if(lines.length===1&&(/^(?:#{2,3}\s+|\d+\.\d+(?:\.\d+)*\s+\S)/.test(p)))out.push({kind:'subhead',text:p.replace(/^#{2,3}\s+/,'')});else if(lines.every(l=>/^[-*•]\s|^\d+[.)]\s/.test(l)))lines.forEach(l=>out.push({kind:'list',text:l}));else out.push({kind:'text',text:p})});ims.filter(im=>im.anchor!=='start').forEach(im=>out.push(ib(im)))}return out}
function blackbookFront(m){const heading=text=>({kind:'heading',text}),text=t=>({kind:'text',text:t}),letterhead=[{kind:'letterhead',text:m.college||'Institution name'},...(m.institutionDetails?[{kind:'center',text:m.institutionDetails}]:[]),{kind:'left',text:'Date: '+(m.reportDate||'____________________')}],signatures={kind:'left',text:`Guide: ${m.guide||'____________________'}\n\nGuide signature: ____________________\n\nDirector / Head signature: ____________________`};let pages=[{cover:true},...paginate([{kind:'heading',text:L('titleofproject')},{kind:'bigtitle',text:m.title}],m)];
 for(let [title,body] of [[L('recommendation'),m.recommendation||'Add the recommendation wording supplied and approved by your institution. The director must review and sign the final document.'],[L('certificate'),m.certificateText||'Add the certificate wording supplied and approved by your institution. Verify all project details before obtaining the required signatures.']])pages.push(...paginate([...letterhead,heading(title),text(body),signatures,{kind:'draft',text:'UNSIGNED DRAFT - NOT AN ISSUED INSTITUTIONAL DOCUMENT'}],m));
 let ack=sections.find(s=>/^(acknowledg(?:e)?ments?|आभार|कृतज्ञता|मनोगत)$/i.test(s.title)),abstract=sections.find(s=>/^(abstract|सारांश)$/i.test(s.title));
 pages.push(...paginate([heading(L('acknowledgement')),...((m.acknowledgement||ack?.paras.join('\n\n')||'Add your own acknowledgement of the people and organisations that helped with this project.').split(/\n\s*\n/).map(text))],m));
 pages.push(...paginate([heading(L('abstract')),...(abstract?.paras.length?abstract.paras:['Add your project abstract in the content area under an Abstract heading.']).map(text),...images.filter(im=>im.section===abstract?.id||im.section===ack?.id).map(im=>{throw Error('Move images from Abstract / Acknowledgement to a chapter before building.')} )],m));return pages}
function renderPreview(){let ps=built.pages;$('pages').innerHTML=ps.map((p,i)=>`<div class="page-shell">${pageHTML(p,i+1,ps.length,built.meta)}</div>`).join('');$('empty').hidden=true;$('count').textContent=`${ps.length} PAGES`;resize();$('downloads').hidden=false;$('previewTools').hidden=false;$('pageJump').innerHTML=ps.map((p,i)=>`<option value="${i}">${i+1} / ${ps.length}${p.cover?' · Cover':p.blocks.find(b=>b.kind==='heading')?' · '+esc(p.blocks.find(b=>b.kind==='heading').text):''}</option>`).join('');reviewChecks();}
function resize(){document.querySelectorAll('#pages .page-shell').forEach(sh=>{let scale=sh.clientWidth/794;sh.style.height=1123*scale+'px';sh.firstElementChild.style.transform=`scale(${scale})`})}window.addEventListener('resize',resize);
async function generate(){if(busy)return;try{if(!$('title').value.trim())throw Error('Add a document title first.');if(!$('content').value.trim())throw Error('Paste your content first.');if($('content').value.length>300000)throw Error('Please use up to 300,000 characters per project.');setBusy(true);status('Measuring content and arranging A4 pages…');if(!sections.length)organise();if(sections.length>150)throw Error('Use up to 150 sections per document.');let meta=Object.fromEntries(metaIds.map(id=>[id,$(id).value.trim()]));meta.lang=$('lang').value;meta.coverStyle=$('coverStyle').value;meta.coverAccent=/^#[0-9a-f]{6}$/i.test($('coverAccent').value)?$('coverAccent').value:'#4c3fd1';meta.type=type;if(type==='blackbook'){meta.font='serif';meta.layout='chapters'}let content=paginate(contentBlocks(meta),meta),front=type==='blackbook'?blackbookFront(meta):[{cover:true}];if(type!=='blackbook'&&$('certificate').checked)front.push(...paginate([{kind:'heading',text:'Certificate · Draft for review'},{kind:'text',text:`This draft certificate relates to the project titled "${meta.title}", prepared by ${meta.student||'[student name]'}${meta.roll?' (Roll / PRN: '+meta.roll+')':''} at ${meta.college||'[institution]'}${meta.course?' for '+meta.course:''}.`},{kind:'text',text:'The institution must review the wording, verify the work and complete the required approvals. This document does not certify completion, originality, assessment or endorsement.'},{kind:'left',text:`Guide / teacher: ${meta.guide||'____________________'}\n\nSignature: ____________________\n\nHead of department: ____________________\n\nDate: ____________________`},{kind:'text',text:'UNSIGNED DRAFT - NOT AN ISSUED CERTIFICATE'}],meta));let tocPages=1,index=[];for(let pass=0;pass<4;pass++){let entries=[];content.forEach((p,i)=>p.blocks.forEach(b=>{if(b.kind==='heading')entries.push({kind:'toc',text:b.text,chapter:b.chapter,number:front.length+tocPages+i+1})}));index=paginate([{kind:'heading',text:type==='blackbook'?L('toc'):L('contents')},...(type==='blackbook'?[{kind:'tochead'}]:[]),...entries],{...meta,layout:'compact'});if(index.length===tocPages)break;tocPages=index.length}let coverProbe={cover:true};$('measure').innerHTML=pageHTML(coverProbe,1,1,meta);let cover=$('measure').querySelector('.cover');if(cover.scrollHeight>cover.clientHeight)throw Error('Cover details are too long. Shorten the title or names.');built={meta,pages:[...front,...index,...content]};renderPreview();let missing=sections.filter(s=>!s.paras.length).map(s=>s.title);status(`${built.pages.length} pages ready. Review every page${missing.length?'. Empty sections: '+missing.join(', '):''}. ${type==='blackbook'&&!sections.some(s=>/references|bibliography|संदर्भ/i.test(s.title))?'No references supplied. Add your real sources before submission.':''}`)}catch(err){status(err.message,true)}finally{setBusy(false)}}
$('generate').onclick=generate;
async function exportPDF(){if(!built||busy)return;setBusy(true);$('pdf').disabled=true;let root=document.createElement('div');root.style.cssText='position:absolute;left:-10000px;top:0;';document.body.append(root);try{let pdf=new jsPDF({unit:'mm',format:'a4',compress:true});for(let i=0;i<built.pages.length;i++){status(`Preparing PDF page ${i+1} of ${built.pages.length}…`);root.innerHTML=pageHTML(built.pages[i],i+1,built.pages.length,built.meta);let page=root.firstElementChild;await Promise.all([...page.querySelectorAll('img')].map(im=>im.decode()));let canvas=await html2canvas(page,{scale:1.6,backgroundColor:'#ffffff',logging:false});$('progress').value=(i+1)/built.pages.length*100;if(i)pdf.addPage();pdf.addImage(canvas.toDataURL('image/jpeg',.92),'JPEG',0,0,210,297);canvas.width=1;canvas.height=1}pdf.save(fileName()+'.pdf');status('PDF downloaded. Its page layout matches the preview.')}catch(err){status('PDF failed: '+err.message+'. Try Print / searchable PDF.',true)}finally{root.remove();setBusy(false);$('pdf').disabled=false}}
$('pdf').onclick=exportPDF;$('print').onclick=()=>window.print();
