pdfjsLib.GlobalWorkerOptions.workerSrc='5-pdf.worker.min.js';
async function pdfToMarkdown(file){let buf=await file.arrayBuffer();let pdf=await pdfjsLib.getDocument({data:buf}).promise;let pages=[];
 for(let n=1;n<=pdf.numPages;n++){let page=await pdf.getPage(n),tc=await page.getTextContent(),rows=[];
  for(let it of tc.items){if(!it.str||!it.str.trim()&&!it.hasEOL)continue;let y=it.transform[5],h=Math.abs(it.transform[3])||it.height||10,x=it.transform[4],row=rows.find(r=>Math.abs(r.y-y)<h*.35);if(!row){row={y,h:0,items:[]};rows.push(row)}row.items.push({x,s:it.str,h});row.h=Math.max(row.h,h)}
  rows.sort((a,b)=>b.y-a.y);pages.push(rows.map(r=>{r.items.sort((a,b)=>a.x-b.x);return{y:r.y,h:r.h,text:r.items.map(i=>i.s).join('').replace(/\s+/g,' ').trim()}}).filter(r=>r.text))}
 let all=pages.flat();if(all.reduce((a,r)=>a+r.text.length,0)<40)throw Error('No selectable text found. This looks like a scanned PDF; scanned PDFs are not supported yet.');
 let freq={};all.forEach(r=>{let k=Math.round(r.h);freq[k]=(freq[k]||0)+r.text.length});let body=+Object.entries(freq).sort((a,b)=>b[1]-a[1])[0][0];
 let rep={};pages.forEach(p=>new Set(p.map(r=>r.text.replace(/\d+/g,'#'))).forEach(t=>rep[t]=(rep[t]||0)+1));
 let out=[],para=[],last=null;const flush=()=>{if(para.length){out.push(para.join(' ').replace(/(\w)- (\w)/g,'$1$2'));para=[]}};
 pages.forEach(p=>{p.forEach((r,i)=>{let norm=r.text.replace(/\d+/g,'#');if(/^\d{1,4}$/.test(r.text)||/^page\s+\d+(\s*(of|\/)\s*\d+)?$/i.test(r.text))return;if(pages.length>2&&rep[norm]>=Math.max(3,pages.length*.6)&&r.text.length<90)return;
  let big=r.h/body,isHead=r.text.length<=110&&!/[.,;]$/.test(r.text)&&(big>=1.18||/^(chapter\s+\d+|\d+(\.\d+)*\s+[A-Z])/i.test(r.text)&&big>=1.05);
  if(isHead){flush();out.push((big>=1.4||/^chapter/i.test(r.text)?'# ':'## ')+r.text.replace(/^chapter\s+\d+\s*[:.-]?\s*/i,'').trim());last=null;return}
  if(last&&Math.abs(last.y-r.y)>body*2.1&&last.p===p){flush()}
  para.push(r.text);last={y:r.y,p}});});flush();
 return out.filter(Boolean).join('\n\n')}
$('importPdf').onchange=async e=>{let f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>25*1024*1024)throw Error('PDF is over 25 MB.');setBusy(true);status('Reading PDF text…');let md=await pdfToMarkdown(f);if(md.length>300000)md=md.slice(0,300000);let cur=$('content').value.trim();if(cur&&confirm('Replace your current text with the PDF text? OK = replace, Cancel = add the PDF text after it.'))cur='';$('content').value=(cur?cur+'\n\n':'')+md;sections=[];$('sectionList').innerHTML='';invalidate();organise();status(`PDF text imported (${sections.length} sections found). Only text is read, not images. Check headings and order below.`)}catch(err){status('PDF import failed: '+err.message,true)}finally{setBusy(false)}};

/* --- AI --- */
async function aiCall(body,tries=3){let base=apiBase();if(!base&&location.hostname!=='localhost')throw Error('AI writing is not connected yet.');for(let t=0;t<tries;t++){let r=await fetch(base+'/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).catch(()=>null);if(r&&r.ok)return r.json();if(r&&r.status===429&&t<tries-1){await new Promise(z=>setTimeout(z,7000));continue}if(r){let j=await r.json().catch(()=>({}));throw Error(j.error||'AI service error ('+r.status+')')}if(t===tries-1)throw Error('Could not reach the AI service. Check your internet and try again.')}}
const SKIPAI=/^(references|bibliography|संदर्भ|acknowledg(?:e)?ments?|आभार|कृतज्ञता|मनोगत)$/i;
$('aiWrite').onclick=async()=>{if(busy)return;let topic=$('aiTopic').value.trim();try{if(topic.length<3)throw Error('Type a topic first, e.g. "Online library management system".');if($('content').value.trim()&&!confirm('AI will write sections into your document. Existing text stays where the headings match; empty template sections get filled. Continue?'))return;setBusy(true);$('aiTopic').disabled=true;let lang=$('lang').value,length=$('aiLength').value;
  organise();let titles=sections.filter(s=>!SKIPAI.test(s.title)).map(s=>s.title);if(titles.length<2){status('Planning the outline…');let o=await aiCall({task:'outline',topic,type,lang});titles=(o.sections||[]).filter(t=>!SKIPAI.test(t));if(!titles.length)throw Error('AI could not plan an outline. Try a clearer topic.');let ex=sections.filter(s=>SKIPAI.test(s.title));sections=[...titles.map((t,i)=>({title:t,paras:[],id:'s'+i})),...ex.map((s,i)=>({...s,id:'s'+(titles.length+i)}))]}
  let n=0,total=sections.filter(s=>!SKIPAI.test(s.title)).length;
  for(let s of sections){if(SKIPAI.test(s.title))continue;n++;let have=s.paras.join('\n\n');if(have&&!/^\[Write your/.test(have)&&have.length>200)continue;status(`Writing section ${n} of ${total}: ${s.title}…`);let r=await aiCall({task:'section',topic,type,lang,length,title:s.title,outline:sections.map(x=>x.title).slice(0,20)});let ps=(r.paragraphs||[]).map(p=>String(p).trim()).filter(Boolean);if(ps.length){s.paras=ps;aiState.used=true}syncContent();renderSections()}
  syncContent();renderSections();renderImages();invalidate();if(!$('title').value.trim())$('title').value=topic.replace(/^./,c=>c.toUpperCase());status(`AI wrote ${total} sections. Read every section, fix facts, and add your real references before submitting.`)}catch(err){syncContent();renderSections();status(err.message,true)}finally{setBusy(false);$('aiTopic').disabled=false}};

/* --- auto diagrams --- */
function drawDiagram(kind,title,nodes,accent){const W=1100,font='"Segoe UI",system-ui,"Noto Sans Devanagari","Nirmala UI",Mangal,sans-serif';let c=document.createElement('canvas'),x=c.getContext('2d');x.font='600 26px '+font;
 const wrap=(t,maxw)=>{let words=String(t).split(/\s+/),lines=[],cur='';for(let w of words){let test=cur?cur+' '+w:w;if(x.measureText(test).width>maxw&&cur){lines.push(cur);cur=w}else cur=test}if(cur)lines.push(cur);return lines.slice(0,3)};
 const box=(bx,by,bw,bh,txt,fill,color)=>{x.fillStyle=fill;x.strokeStyle=accent;x.lineWidth=3;x.beginPath();x.roundRect(bx,by,bw,bh,16);x.fill();x.stroke();x.fillStyle=color;x.textAlign='center';x.textBaseline='middle';let ls=wrap(txt,bw-28),lh=32;ls.forEach((l,i)=>x.fillText(l,bx+bw/2,by+bh/2+(i-(ls.length-1)/2)*lh))};
 const arrow=(x1,y1,x2,y2)=>{x.strokeStyle='#52606d';x.fillStyle='#52606d';x.lineWidth=3;x.beginPath();x.moveTo(x1,y1);x.lineTo(x2,y2);x.stroke();let a=Math.atan2(y2-y1,x2-x1);x.beginPath();x.moveTo(x2,y2);x.lineTo(x2-14*Math.cos(a-.4),y2-14*Math.sin(a-.4));x.lineTo(x2-14*Math.cos(a+.4),y2-14*Math.sin(a+.4));x.closePath();x.fill()};
 nodes=nodes.slice(0,8);let bh=88;
 if(kind==='layers'){let h=nodes.length*(bh+26)+30;c.width=W;c.height=h;x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,h);x.font='600 26px '+font;nodes.forEach((t,i)=>{box(150,20+i*(bh+26),800,bh,t,i%2?'#f4f7ff':'#eef9f4','#1f2933');if(i<nodes.length-1)arrow(550,20+i*(bh+26)+bh,550,20+(i+1)*(bh+26))})}
 else if(kind==='hub'){let h=620;c.width=W;c.height=h;x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,h);x.font='600 26px '+font;let [first,...rest]=nodes,cx=W/2,cy=h/2,r=Math.min(240,cy-80);rest.forEach((t,i)=>{let a=-Math.PI/2+i*2*Math.PI/rest.length,px=cx+Math.cos(a)*r*1.9,py=cy+Math.sin(a)*r;arrow(cx+Math.cos(a)*120,cy+Math.sin(a)*60,px-Math.cos(a)*100,py-Math.sin(a)*40)});rest.forEach((t,i)=>{let a=-Math.PI/2+i*2*Math.PI/rest.length,px=cx+Math.cos(a)*r*1.9,py=cy+Math.sin(a)*r;box(px-110,py-bh/2,220,bh,t,'#f4f7ff','#1f2933')});box(cx-130,cy-60,260,120,first,accent,'#fff')}
 else{let per=nodes.length>4?Math.ceil(nodes.length/2):nodes.length,rows=Math.ceil(nodes.length/per),gap=60,bw=Math.min(240,(W-80-(per-1)*gap)/per),h=rows*(bh+70)+10;c.width=W;c.height=h;x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,h);x.font='600 26px '+font;let pos=nodes.map((t,i)=>{let r=Math.floor(i/per),k=i%per,cnt=Math.min(per,nodes.length-r*per),total=cnt*bw+(cnt-1)*gap,sx=(W-total)/2;return{x:sx+k*(bw+gap),y:20+r*(bh+70)}});pos.forEach((p,i)=>{if(i<pos.length-1){let q=pos[i+1];if(q.y===p.y)arrow(p.x+bw+4,p.y+bh/2,q.x-4,q.y+bh/2);else arrow(p.x+bw/2,p.y+bh+4,q.x+bw/2,q.y-4)}});nodes.forEach((t,i)=>box(pos[i].x,pos[i].y,bw,bh,t,i%2?'#f4f7ff':'#eef9f4','#1f2933'))}
 return{data:c.toDataURL('image/png'),w:c.width,h:c.height}}
const accentColor=()=>/^#[0-9a-f]{6}$/i.test($('coverAccent').value)?$('coverAccent').value:'#4c3fd1';
function listNodes(s){let items=s.paras.flatMap(p=>p.split('\n')).map(l=>l.trim()).filter(l=>/^[-*•]\s|^\d+[.)]\s/.test(l)).map(l=>l.replace(/^[-*•]\s*|^\d+[.)]\s*/,'').split(/[:\-–—.]/)[0].trim()).filter(Boolean);return items.length>=3?items.slice(0,8).map(t=>t.length>42?t.slice(0,40)+'…':t):null}
async function addDiagram(s,{quiet}={}){let nodes=listNodes(s),kind='flow',cap=s.title;if(!nodes){let text=s.paras.join('\n').slice(0,3500);if(text.length<80)throw Error('Section "'+s.title+'" has too little text for a diagram.');let r=await aiCall({task:'diagram',lang:$('lang').value,title:s.title,text});nodes=(r.nodes||[]).map(String).filter(Boolean).slice(0,8);kind=['flow','layers','hub'].includes(r.kind)?r.kind:'flow';cap=r.title||s.title;if(nodes.length<3)throw Error('Could not find enough steps in "'+s.title+'".')}
 let d=drawDiagram(kind,cap,nodes,accentColor());if(images.length>=12)throw Error('Maximum 12 images. Remove one first.');images.push({name:'diagram-'+s.id+'.png',caption:'Diagram: '+cap,data:d.data,w:d.w,h:d.h,anchor:'end',automatic:false,section:s.id,diagram:true});renderImages();invalidate();if(!quiet)status('Diagram added under "'+s.title+'". Check it in the image list.')}
const DIAGSEC=/(method|design|architecture|implementation|system|process|working|flow|proposed|analysis|workflow|कार्यप्रणाली|प्रक्रिया|रचना|पद्धत)/i;
$('autoDiagrams').onclick=async()=>{if(busy)return;try{organise();let targets=sections.filter(s=>!SKIPAI.test(s.title)&&DIAGSEC.test(s.title)&&s.paras.length&&!images.some(i=>i.section===s.id&&i.diagram)).slice(0,4);if(!targets.length)throw Error('No suitable sections found. Use "+ Auto diagram" inside a section instead.');setBusy(true);let ok=0,errs=[];for(let s of targets){status('Drawing diagram for '+s.title+'…');try{await addDiagram(s,{quiet:true});ok++}catch(e){errs.push(e.message)}}status(`${ok} diagram${ok===1?'':'s'} added.${errs.length?' '+errs[0]:''} Review captions and placement below.`,!ok)}catch(err){status(err.message,true)}finally{setBusy(false)}};
function wireDiagramButtons(){document.querySelectorAll('[data-diag]').forEach(b=>b.onclick=async()=>{if(busy)return;try{setBusy(true);status('Drawing diagram…');await addDiagram(sections[+b.dataset.diag])}catch(e){status(e.message,true)}finally{setBusy(false)}})}
const _rs=renderSections;renderSections=function(){_rs();wireDiagramButtons()};

