function reviewChecks(){if(!built)return;let m=built.meta,notes=[];if(!m.student&&!m.students)notes.push('Add student names before submission.');if(!m.college)notes.push('Add your college / institution.');if(m.type==='blackbook'){if(!m.university)notes.push('University is blank.');if(!m.degree&&!m.course)notes.push('Degree / course is blank.');if(!sections.some(s=>/^(abstract|सारांश)$/i.test(s.title)&&s.paras.length))notes.push('Add an Abstract section.');if(!m.recommendation||!m.certificateText)notes.push('Institutional pages contain placeholders. Supply approved wording and obtain real signatures.');}if(!sections.some(s=>/references|bibliography|संदर्भ/i.test(s.title)))notes.push('No references section. Add the actual sources you used.');if(sections.some(s=>!s.paras.length))notes.push('Some sections have no text.');if(sections.some(s=>s.paras.some(p=>/^\[Write your /.test(p))))notes.push('Some sections still show template placeholder text. Write them or remove them.');if(aiState.used)notes.push('Parts of this were written by AI. Read everything, check the facts, and add real references. Do not submit unchecked AI text as your own research.');if(m.student==='Demo Student')notes.push('This is fictional sample content. Replace it with your own work.');$('reviewChecks').hidden=false;$('reviewChecks').innerHTML=`<strong>${notes.length?'Review before submission':'Layout built. Final review needed.'}</strong>${notes.length?'<ul>'+notes.map(t=>'<li>'+esc(t)+'</li>').join(''):'<p>Check every page, image caption, fact and source before submitting.</p>'}`;}
$('pageJump').onchange=()=>document.querySelectorAll('#pages .page-shell')[+$('pageJump').value]?.scrollIntoView({behavior:'smooth',block:'start'});
$('zoom').onclick=()=>{if(!built)return;let i=+$('pageJump').value;$('dialogTitle').textContent='Page '+(i+1)+' of '+built.pages.length;$('dialogPaper').innerHTML=pageHTML(built.pages[i],i+1,built.pages.length,built.meta);$('pageDialog').showModal();$('dialogPaper').style.overflow='hidden';$('actualSize').textContent='100% size';let scale=Math.min(1,($('pageDialog').clientWidth-32)/794);$('dialogPaper').style.height=1123*scale+'px';$('dialogPaper').firstElementChild.style.transform=`scale(${scale})`;};
$('closeDialog').onclick=()=>$('pageDialog').close();$('pageDialog').onclick=e=>{if(e.target===$('pageDialog'))$('pageDialog').close()};
$('importText').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>1200000)throw Error('Use a text file smaller than 1.2 MB.');let text=await f.text();if(text.length>300000)throw Error('Use up to 300,000 characters.');if($('content').value.trim()&&!confirm('Replace the current text with this file?'))return;$('content').value=text;sections=[];updateCount();organise();status('Text imported. Review section titles and image placement.')}catch(err){status(err.message,true)}finally{e.target.value=''}};
$('reset').onclick=()=>{if(!confirm('Start a new document? Unsaved work will be cleared. Save a backup first to keep it.'))return;metaIds.forEach(id=>{if(!['font','layout'].includes(id))$(id).value=''});$('font').value='serif';$('layout').value='compact';$('content').value='';$('certificate').checked=false;images=[];sections=[];chooseType('assignment');renderSections();renderImages();updateCount();status('New document ready.');window.scrollTo({top:0,behavior:'smooth'})};
updateCount();

$('actualSize').onclick=()=>{let full=$('actualSize').textContent==='100% size',scale=full?1:Math.min(1,($('pageDialog').clientWidth-32)/794);$('dialogPaper').style.overflow=full?'auto':'hidden';$('dialogPaper').style.height=1123*scale+'px';$('dialogPaper').firstElementChild.style.transform=`scale(${scale})`;$('actualSize').textContent=full?'Fit page':'100% size'};
